    $(document).on("change", "select.getByMasterRoom", function (e) {
        var obj = $(this);
        var masterroom = obj.val();
        var form = obj.closest('form');
        if(masterroom == '0' || masterroom == '') {
            //alert('This Master Room is not valid till now. Please use correct Master Room');
            form.find('input[name=reservationid]').val('0');
            form.find('input[name=name]').val('');
            form.find('input[name=cell]').val('');
            form.find('input[name=email]').val('');
            form.find('input[name=address]').val('');
        } else {
            var url = obj.data('action');
            $.ajax({
                url : url,
                type: "GET",
                data: {masterroom:masterroom},
                dataType:'JSON',
                success: function(result)
                {
                    if(result.status == '0'){
                        alert('This Master Room is not valid till now. Please use correct Master Room');
                        form.find('input[name=reservationid]').val('0');
                        form.find('input[name=name]').val('');
                        form.find('input[name=cell]').val('');
                        form.find('input[name=email]').val('');
                        form.find('input[name=address]').val('');
                    } else {
                        var data = result.data;
                        var guest = data.guest;
                        var name = guest.nameprefix+' '+guest.firstname+' '+guest.lastname;
                        form.find('input[name=reservationid]').val(data.refid);
                        form.find('input[name=name]').val(name);
                        form.find('input[name=cell]').val(guest.mobile);
                        form.find('input[name=email]').val(guest.email);
                        form.find('input[name=address]').val(guest.permanentaddress);
                    }
                },
                error: function (data)
                {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        }


    });



