function controlPaymentBlock(obj){
    var form = obj.closest('form');
    var block = obj.closest('.payment-block');
    var val = obj.val();
    var data = obj.data('bank');
    var option;
    if(val == 'BANK' || val == 'MOBILE BANK' || val == 'CREDIT CARD')  {
        block.find('.due-block').hide();
        block.find('.requiredondue').prop('required',false);

        block.find('.suspension-block').hide();
        block.find('.requiredonsuspnsion').prop('required',false);

        block.find('.bank-block').show();
        block.find('.requiredonbank').prop('required',true);

        switch(val){
            case 'BANK':
                option = data.bank;
                break;
            case 'MOBILE BANK':
                option = data.mobilebank;
                break;
            case 'CREDIT CARD':
                option = data.creditcard;
                break;
        }

        var optiontext = '';
        for(i=0; i < option.length; i++){
            optiontext += '<option value="'+option[i].id+'">'+option[i].name+'</option>';
        }
        if(block.find('.bankid').html() != optiontext) {
            block.find('.bankid').html(optiontext).trigger('chosen:updated');
        }

    } else if(val == 'SUSPENSION') {
        block.find('.bank-block').hide();
        block.find('.due-block').hide();
        block.find('.requiredonbank').prop('required',false);
        block.find('.requiredondue').prop('required',false);

        block.find('.suspension-block').show();
        block.find('.requiredonsuspension').prop('required',true);
    }
    else if(val == 'DUE' || val == 'PARTY') {
        block.find('.bank-block').hide();
        block.find('.suspension-block').hide();
        block.find('.requiredonbank').prop('required',false);
        block.find('.requiredonsuspnsion').prop('required',false);

        block.find('.due-block').show();
        block.find('.requiredondue').prop('required',true);
    } else {

        block.find('.due-block').hide();
        block.find('.suspension-block').hide();
        block.find('.bank-block').hide();
        block.find('.requiredondue').prop('required',false);
        block.find('.requiredonsuspnsion').prop('required',false);
        block.find('.requiredonbank').prop('required',false);
    }
}



function controlSusPartyBlock(){
    if($('#adjustsuspension').length > 0){
        var obj = $('#adjustsuspension');
        var form = obj.closest('form');
        var target = obj.data('target');
        if(obj.is(':checked')) {
            form.find('#'+target).show().find('select').prop('required',true);
        } else {
            form.find('#'+target).hide().find('select').prop('required',false);
        }
    }
}

function setCartGrid(tbl, data){
    /////
    var form = tbl.closest('form');
    var rows = data.rows;
    var row;
    var tbody;
    for(i=0; i < rows.length; i++){
        row = rows[i];
        tbody += '<tr data-itemid="'+row.itemid+'" data-item="'+row.itemcode+':'+row.itemname+'">'
            +'<td class="text-left">'+row.itemcode+'</td>'
            +'<td class="text-left">'+row.itemname+'</td>'
            +'<td class="text-right qty">'+row.qty+'</td>'
            +'<td class="text-right rate">'+row.rate+'</td>'
            +'<td class="text-right price">'+row.price+'</td>'
            +'<td class="text-center">'
            +'<a class="btn btn-warning edit" title="Edit"><i class="fas fa-pencil-alt"></i></a>  '
            +'<a class="btn btn-danger delete" title="Remove"><i class="fas fa-trash-alt"></i></a>'
            +'</td>'
            +'</tr>';
    }
    tbl.find('tbody').html(tbody);
    tbl.find('tfoot').find('#tot-qty').html(data.total.qty);
    tbl.find('tfoot').find('#tot-price').html(data.total.price);
    form.find('#id').val(data.id);
    form.find('.open-sales-payment-modal').data('id',data.id);
    /////


    tbl.find('tbody').on( 'click', 'tr td .edit', function (e) {
        e.preventDefault();
        setCartGridEdit($(this),true);
    });


    tbl.find('tbody').on( 'click', 'tr td .delete', function (e) {
        e.preventDefault();
        setCartGridEdit($(this),false);
    });
}

function setCartGridEdit(obj,pickup) {
    var tr = obj.closest('tr');
    var tbl = tr.closest('table');
    var form = tbl.closest('form');
    var refid = form.find('#id').val();
    var url = tbl.data('action');
    var qty = tr.find('.qty').text();
    var rate = tr.find('.rate').text();
    var itemid = tr.data('itemid');
    var item = tr.data('item');
    if(pickup){
        form.find('#qty').val(qty);
        form.find('#rate').val(rate);
        form.find('select#itemid').val(itemid);
        form.find('input[name=itemid]').val(itemid);
        form.find('input[name=itemid]').next('.input-group').find('input.combobox').val(item);
    }
    $.ajax({
        url : url,
        type: "GET",
        data : {id:refid, itemid:itemid, qty:qty, rate:rate},
        dataType:'JSON',
        success: function(data)
        {
            if(data.status == '1'){
                setCartGrid(tbl,data);
                tr.remove();
            }
        },
        error: function (data)
        {
            console.log('An error occurred.');
            console.log(data);
        }
    });
}


function salesDiscountCalcultion(calculateon){
    calculateon = (calculateon === undefined)?'per':calculateon;

    var form = $('.frm-modal-payment-calculation');

    var discount_per_obj = form.find('input[name=discount_per]');
    var discount_amount_obj = form.find('input[name=discount_amount]');

    var discount_per = parseInt(discount_per_obj.val());
    var discount_amount = parseFloat(discount_amount_obj.val());
    var amount = parseFloat(form.find('#priceaftercharge').text());
    var amount_after_discount = parseFloat(form.find('#netprice').text());

    if(calculateon == 'per'){
        discount_amount = (discount_per * amount) / 100;
        discount_amount_obj.val(discount_amount);
    } else if(calculateon == 'amount'){
        discount_per = (discount_amount * 100) / amount;
        discount_per_obj.val(discount_per);
    }
    amount_after_discount = amount - discount_amount;
    form.find('#netprice').text(Math.round(amount_after_discount));
}



function getPaymentSum(){
    var tbl = $('#payment-table');
    var paymenttotal = 0;
    tbl.find('tbody').find('tr').each(function() {
        paymenttotal += parseInt($(this).find('.payment-amount').val());
    });
    paymenttotal = Math.round(paymenttotal);
    var netprice = parseInt(tbl.closest('form').find('#netprice').text())
    var changeamount = paymenttotal - netprice;
    changeamount = (changeamount > 0)?changeamount:0;
    $('#total-payment-amount').text(Math.round(paymenttotal));
    tbl.closest('form').find('#changeamount').text(Math.round(changeamount));
}

function applyCharge(amount,per){
    amount = parseFloat(amount);
    per = parseInt(per);
    if(per > 0){
        var charge = (per * amount) / 100;
        var sum = amount + charge;
        return {"charge":charge, "sum":sum};
    }
    return {"charge":per, "sum":amount};
}

function loadDefaultValue(){
    if($('select').length > 0){
        $( 'select' ).each(function() {
            var obj = $(this);
            if (typeof obj.data('value') !== 'undefined') {
                obj.val(obj.data('value'));
            }
        });
    }

    if($('input[type=checkbox]').length > 0){
        $( 'input[type=checkbox]' ).each(function() {
            var obj = $(this);
            if (typeof obj.data('check') !== 'undefined') {
                if(obj.data('check') == '1'){
                    obj.prop( "checked", true );
                }
            }
        });
    }
}


function gridReload(){
    location.reload();
}

function redirect(page){
    window.location.replace(page);
}

